/* ChemLab's service worker. Written by hand, not generated by a plugin, because the rules it
 * implements are the app's rules and they should be readable:
 *
 *   - the data files are cache-first: 1.2 MB of JSON you already have is never fetched again
 *   - data/manifest.json is network-first: it is the one thing small enough to ask about, and it
 *     is how the app learns a new build exists
 *   - nothing is ever fetched from another origin: no CDN, no font, no analytics, no map tiles
 *   - a new version waits for you to say so; it does not reload the app under your fingers
 *
 * scripts/gen-sw.mjs replaces the PRECACHE list at build time with the files actually in dist.
 */

/*__BUILD__*/ const BUILD = "dev"; /*__END_BUILD__*/
/*__PRECACHE__*/
const PRECACHE = ["./", "./index.html", "./manifest.webmanifest", "./icons/icon-192.png", "./icons/icon-512.png", "./icons/icon-maskable-512.png", "./icons/favicon-32.png", "./data/chemlab.json.gz", "./data/combinations.json.gz"];
/*__END_PRECACHE__*/
const DATA_URLS = ["./data/chemlab.json.gz", "./data/combinations.json.gz"];
const MANIFEST = "./data/manifest.json";

const SHELL = `chemlab-shell-${BUILD}`;
const DATA = "chemlab-data"; // one cache that survives a shell update, so data is never re-fetched

self.addEventListener("install", (e) => {
  e.waitUntil(
    (async () => {
      const c = await caches.open(SHELL);
      // allSettled: an icon that is not there (a bare copy of the files) must not fail the install
      const r = await Promise.allSettled(PRECACHE.map((u) => c.add(new Request(u, { cache: "reload" }))));
      return { cached: r.filter((x) => x.status === "fulfilled").length, failed: r.filter((x) => x.status === "rejected").length };
    })(),
  );
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k !== SHELL && k !== DATA).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

async function put(cacheName, req) {
  const res = await fetch(new Request(req, { cache: "reload" }));
  if (res && res.ok) (await caches.open(cacheName)).put(req, res.clone());
  return res;
}
async function cached(req) {
  return (await caches.match(req, { ignoreVary: true })) || null;
}

/** the data: cache first, fetch only what is missing */
async function dataResponse(req) {
  const hit = await cached(req);
  if (hit) return hit;
  try {
    return await put(DATA, req);
  } catch {
    return Response.error();
  }
}

/** the manifest: ask the network, fall back to whatever is cached, and compare build ids.
 *  The cached copy has to be read *before* it is overwritten, or the comparison always agrees
 *  and a new build is never noticed — which is the bug this whole function exists to avoid. */
async function manifestResponse(req) {
  const before = await cached(req);
  let stored = null;
  if (before) {
    try {
      stored = (await before.clone().json()).build_id ?? null;
    } catch {
      stored = null;
    }
  }
  let fresh = null;
  try {
    fresh = await put(DATA, req);
  } catch {
    fresh = null;
  }
  if (!fresh || !fresh.ok) {
    tell({ type: "chemlab:offline", why: "the manifest could not be reached; this is the cached copy" });
    return before || new Response(JSON.stringify({ error: "no manifest, offline" }), { headers: { "content-type": "application/json" } });
  }
  let live = null;
  try {
    live = (await fresh.clone().json()).build_id ?? null;
  } catch {
    live = null;
  }
  if (stored && live && stored !== live) {
    // the build changed: pull the new data down in the background, then say so
    try {
      await Promise.all(DATA_URLS.map((u) => put(DATA, new Request(u, { cache: "reload" }))));
      tell({ type: "chemlab:new-data", build_id: live, from: stored });
    } catch {
      tell({ type: "chemlab:new-data-failed", build_id: live, from: stored });
    }
  } else if (live) {
    tell({ type: "chemlab:current", build_id: live });
  }
  return fresh;
}

/** the shell: network when there is one, cache when there is not, and a navigation always lands */
async function shellResponse(req) {
  try {
    return await put(SHELL, req);
  } catch {
    const hit = await cached(req);
    if (hit) return hit;
    if (req.mode === "navigate") {
      const idx = await cached("./index.html");
      if (idx) return idx;
    }
    return Response.error();
  }
}

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) {
    // refusing here is the point: the app never needs a third party, so a request to one is a bug
    e.respondWith(Response.error());
    return;
  }
  if (url.pathname.endsWith(MANIFEST.replace(/^\./, "")) || url.pathname.endsWith("/data/manifest.json")) {
    e.respondWith(manifestResponse(req));
    return;
  }
  if (url.pathname.includes("/data/")) {
    e.respondWith(dataResponse(req));
    return;
  }
  e.respondWith(shellResponse(req));
});

async function tell(msg) {
  const list = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
  for (const c of list) c.postMessage(msg);
}

self.addEventListener("message", (e) => {
  const d = e.data || {};
  if (d.type === "chemlab:check") {
    e.waitUntil(
      (async () => {
        const data = await Promise.all(
          DATA_URLS.map(async (u) => ({ url: u, hit: !!(await caches.match(u, { ignoreVary: true })) })),
        );
        const meta = await (await caches.open(SHELL)).keys();
        const m = await cached(MANIFEST);
        let build = BUILD;
        try {
          if (m) build = (await m.json()).build_id ?? BUILD;
        } catch {
          /* the cached manifest is unreadable; the build id from the file name will do */
        }
        (e.source || self).postMessage({
          type: "chemlab:state",
          build,
          shell: BUILD,
          assets: meta.length,
          precache: PRECACHE.length,
          data,
          manifest_cached: !!m,
        });
      })(),
    );
    return;
  }
  if (d.type === "chemlab:refresh-data") {
    e.waitUntil(
      (async () => {
        try {
          await Promise.all(DATA_URLS.map((u) => put(DATA, new Request(u, { cache: "reload" }))));
          await put(DATA, new Request(MANIFEST, { cache: "reload" }));
          (e.source || self).postMessage({ type: "chemlab:data-refreshed", ok: true });
        } catch (err) {
          (e.source || self).postMessage({ type: "chemlab:data-refreshed", ok: false, why: String(err && err.message ? err.message : err) });
        }
      })(),
    );
    return;
  }
  if (d.type === "chemlab:skip") self.skipWaiting();
});
